// GENERATED by scripts/katalon/convert.mjs: the helper functions every Katalon script defines
// (wait for BlockUI, click with retry, PrimeFaces dropdown by index, ...), converted once and shared.
// A script whose copy differs keeps its own version inline.
import { WebUI, TestObject, ConditionType, FailureHandling, WebUiCommonHelper, gAssert, Arrays } from './runtime';

export async function toInt(v: any, defaultVal: any = 0) {
	if (v == null) return defaultVal
	return Number(v.toString().trim()).intValue()
}

export async function waitBlockUI(timeout: any = 30) {
	let blockUI: any = new TestObject('blockUI')
	blockUI.addProperty("xpath", ConditionType.EQUALS,
		"//*[contains(@class,'ui-blockui') or contains(@class,'blockUI') or contains(@class,'ui-widget-overlay')]"
	)

	if (await WebUI.verifyElementPresent(blockUI, 1, FailureHandling.OPTIONAL)) {
		await WebUI.waitForElementNotVisible(blockUI, timeout, FailureHandling.OPTIONAL)
	}
}

export async function wVisible(obj: any, timeout: any = 1) {
	await waitBlockUI(Math.min(timeout, 1))
	await WebUI.waitForElementVisible(obj, timeout, FailureHandling.STOP_ON_FAILURE)
}

export async function wClickable(obj: any, timeout: any = 1) {
	await wVisible(obj, timeout)
	await WebUI.waitForElementClickable(obj, timeout, FailureHandling.STOP_ON_FAILURE)
}

export async function c(obj: any, timeout: any = 1) {
	for (let i =0; i<2; i++) {
		try {
			await wClickable(obj, timeout)
			await WebUI.scrollToElement(obj, 1, FailureHandling.OPTIONAL)
			await WebUI.click(obj)
			await waitBlockUI(1)
			return
		} catch (e: any) {
			await WebUI.delay(0.3)
		}
	}
	// last try
	await wClickable(obj, timeout)
	await WebUI.click(obj)
	await waitBlockUI(1)
}

export async function dc(obj: any, timeout: any = 1) {
	try {
		await wClickable(obj, timeout)
		await WebUI.scrollToElement(obj, 1, FailureHandling.OPTIONAL)
		await WebUI.doubleClick(obj, FailureHandling.OPTIONAL)
		await waitBlockUI(1)
	} catch (e: any) {
		await WebUI.doubleClick(obj, FailureHandling.OPTIONAL)
		await waitBlockUI(1)
	}
}

export async function t(obj: any, value: any, timeout: any = 1) {
	await wVisible(obj, timeout)
	await WebUI.scrollToElement(obj, 1, FailureHandling.OPTIONAL)
	await WebUI.setText(obj, (value == null ? "" : value.toString()))
}

export const setZoneQtyByRow = async (rowIndex: any, qtyValue: any) => {
	let xpath: any = `//div[contains(@class,'ui-dialog')]//input[contains(@id,'specZoneQtyTbl:${rowIndex}:zoneQty')]`

	let qtyObj: any = new TestObject("zoneQty_" + rowIndex)
	qtyObj.addProperty("xpath", ConditionType.EQUALS, xpath)

	await WebUI.waitForElementVisible(qtyObj, 20)
	let qtyEl: any = await WebUiCommonHelper.findWebElement(qtyObj, 20)

	await WebUI.executeJavaScript(
		`
        arguments[0].value = arguments[1];
        arguments[0].dispatchEvent(new Event('input', { bubbles: true }));
        arguments[0].dispatchEvent(new Event('change', { bubbles: true }));
        `,
		Arrays.asList(qtyEl, qtyValue)
	)

	await waitBlockUI(30)
	await WebUI.delay(0.5)
}

export const setUnitPriceByRow = async (rowIndex: any, unitPriceValue: any) => {
	let xpath: any = `//div[contains(@class,'ui-dialog')]//input[contains(@id,'specAnswerTbl:${rowIndex}:ratePerUomAns')]`

	let priceObj: any = new TestObject("unitPrice_" + rowIndex)
	priceObj.addProperty("xpath", ConditionType.EQUALS, xpath)

	await WebUI.waitForElementVisible(priceObj, 20)
	let priceEl: any = await WebUiCommonHelper.findWebElement(priceObj, 20)

	await WebUI.executeJavaScript(
		`
        arguments[0].value = arguments[1];
        arguments[0].dispatchEvent(new Event('input', { bubbles: true }));
        arguments[0].dispatchEvent(new Event('change', { bubbles: true }));
        `,
		Arrays.asList(priceEl, unitPriceValue)
	)

	await waitBlockUI(30)
	await WebUI.delay(0.5)
}

export async function up(obj: any, filePath: any, timeout: any = 1) {
	await wVisible(obj, timeout)
	await WebUI.uploadFile(obj, filePath)
	await waitBlockUI(1)
}

export async function openPFDropdown(triggerObj: any) {

	let panelOpen: any = new TestObject('pfPanelOpen')
	panelOpen.addProperty("xpath", ConditionType.EQUALS,
		"//div[contains(@class,'ui-selectonemenu-panel') and contains(@style,'display: block')]"
	)

	await c(triggerObj, 20)
	await WebUI.delay(0.3)

	if (!await WebUI.waitForElementVisible(panelOpen, 1, FailureHandling.OPTIONAL)) {
		await c(triggerObj, 20)
		await WebUI.delay(0.3)
		await WebUI.waitForElementVisible(panelOpen, 3, FailureHandling.OPTIONAL)
	}
}

export async function clickPFOptionByIndex(index0: any) {
	let opt: any = new TestObject("pfOpt_" + index0)
	opt.addProperty("xpath", ConditionType.EQUALS,
		`(//div[contains(@class,'ui-selectonemenu-panel') and contains(@style,'display: block')]//li[contains(@class,'ui-selectonemenu-item')])[${index0 + 1}]`
	)

	await c(opt, 20)
	await WebUI.delay(0.2)
	await waitBlockUI(20)
}

export async function selectDropdownByIndex(dropdownObj: any, indexFromData: any) {

	let idx0: any = await toInt(indexFromData) // data already 0-based

	for (let attempt = 0; attempt < 3; attempt++) {
		try {
			await wVisible(dropdownObj, 20)
			let el: any = await WebUiCommonHelper.findWebElement(dropdownObj, 10)
			let tag: any = await el.getTagName()

			if (tag != null && tag.equalsIgnoreCase("select")) {
				await WebUI.selectOptionByIndex(dropdownObj, idx0)
				await WebUI.delay(0.3)
				await waitBlockUI(20)
			} else {
				await openPFDropdown(dropdownObj)
				await clickPFOptionByIndex(idx0)
			}
			return
		} catch (e: any) {
			await WebUI.delay(0.5)
		}
	}

	gAssert(false, "❌ Dropdown failed (stale/DOM refresh): " + dropdownObj.getObjectId())
}
